mapper.select:
select u.user_id, u.user_name, u.phone_num, u.profile_img, date_format(u.last_update, '%Y-%m-%d %H:%i:%s') as last_updated, date_format(u.last_update, '%Y-%m-%d %H:%i:%s') as create_time, all_uar.assigned_region_id, all_uar.user_id as assigned_user_id, all_uar.region_id, all_fr.sido_name, all_fr.name as region_name, date_format(all_uar.create_time, '%Y.%m.%d') as assigned_date from user u inner join user_assigned_region target_uar on u.user_id = target_uar.user_id inner join fire_region target_fr on target_uar.region_id = target_fr.region_id left join user_assigned_region all_uar on u.user_id = all_uar.user_id left join fire_region all_fr on all_uar.region_id = all_fr.region_id where u.delete_flg = 0 and u.role_id = 1
and target_uar.region_id = #{regionId}
order by u.last_update desc, all_uar.create_time asc
